  const out={...row},canonical=text(out.normalized_name||out.normalizedName||out.name).toLowerCase().replace(/[^a-z0-9]+/g,"");
  const sourceText=[out.reported_name,out.reportedName,out.source_raw_text,out.sourceLine,out.sourceContext].map(text).join(" ");
