   raw:sources.reduce((sum,item)=>sum+item.raw,0),
   unique:sources.reduce((sum,item)=>sum+item.unique,0),
   merged:sources.reduce((sum,item)=>sum+item.merged,0),
   excluded:sources.reduce((sum,item)=>sum+item.excluded,0),
   sources
