   const sample=text(row?.value===0?0:row?.value??row?.valueNumeric??row?.value_numeric),normal=text(row?.comparatorLevel??row?.comparator_level)||(text(row?.reference).match(/(?:Comparator|Normal(?:\s+Levels?)?)\s*[:=]?\s*(-?\d+(?:[.,]\d+)?)/i)||[])[1]||"",reported=text(row?.reportedResult||row?.reported_result||"");
