 function buildModel(source,selectedPatient,options,ctcData={onco:[],specialized:[],labRows:[],reportCount:0,rowCount:0,verifiedCount:0,reviewCount:0,excludedCount:0,dateStart:"",dateEnd:""}){
  const verifiedRows=source.filter(row=>row?.status==="VERIFIED"),deduplicatedRows=deduplicateBookletRows(verifiedRows),importAudit=bookletImportAudit(verifiedRows,deduplicatedRows);
  const scoped=periodRows(deduplicatedRows.map(row=>prepareBookletRow(row,selectedPatient)),options.period);
  // OncoTrail and METASTAT belong only to the specialised CTC section.  They
  // must not reappear as ordinary laboratory rows, category counts or trends.
  const specimenContextRows=scoped.filter(row=>Boolean(row?.specimenInterference||row?.specimen_interference));
  const reportScoped=scoped.filter(row=>!ctcReportType(row)&&!Boolean(row?.specimenInterference||row?.specimen_interference));
  reportScoped.forEach(row=>{
   const code=canonicalAnalyteName(row);
   row._bookletSpecimenInterference=specimenContextRows.filter(item=>canonicalAnalyteName(item)===code).map(item=>({date:rowDate(item),value:valueText(item),source:sourceDocument(item)}));
  });
  const duplicateResultsSuppressed=Math.max(0,verifiedRows.length-deduplicatedRows.length);
  const latest=latestByTest(reportScoped),masuyamaLatest=latest.filter(row=>diagnosticFamilyId(row)==="MASUYAMA"),inbodyLatest=latest.filter(row=>diagnosticFamilyId(row)==="INBODY"),generalLatest=latest.filter(isGeneralBookletRow),specializedLatest=latest.filter(row=>!isGeneralBookletRow(row));
  // v10.270 — General Laboratory and Specialized Diagnostics are separate
  // reporting layers. Method-specific classes, titers, food cutoffs, body
  // composition fields and oncology assays must never inflate general High/Low counts.
  const counts={abnormal:0,followup:0,context:0,normal:0};
  generalLatest.forEach(row=>counts[statusOf(row)]++);
  const rank=row=>options.abnormalFirst?(STATUS[statusOf(row)]?.rank??9):0;
  const sortedLatest=[...latest].sort((a,b)=>rank(a)-rank(b)||rowSystemLabel(a).localeCompare(rowSystemLabel(b))||text(a.name).localeCompare(text(b.name)));
  const priority=[...generalLatest].sort((a,b)=>rank(a)-rank(b)||rowSystemLabel(a).localeCompare(rowSystemLabel(b))||text(a.name).localeCompare(text(b.name))).filter(row=>statusOf(row)!=="normal");
  const groups=new Map();
  sortedLatest.forEach(row=>{
   const key=bookletGroupKey(row);
   if(key==="Masuyama Immunological")return;
   if(!groups.has(key))groups.set(key,[]);
   groups.get(key).push(row)
  });
  const trends=sortedLatest.filter(isGeneralBookletRow).map(row=>({row,series:seriesFor(row,reportScoped)})).filter(item=>item.series.length>=2)
   .sort((a,b)=>(STATUS[statusOf(a.row)]?.rank??9)-(STATUS[statusOf(b.row)]?.rank??9)||text(a.row.name).localeCompare(text(b.row.name)));
  const dates=[...reportScoped.map(rowDate),ctcData.dateStart,ctcData.dateEnd].filter(Boolean).sort();
  const sourceAudit=buildSourceAudit(reportScoped,ctcData,importAudit);
  const diagnosticModules=specializedModuleGroups(specializedLatest);
  return{patient:selectedPatient,options,rows:reportScoped,latest:sortedLatest,generalLatest,specializedLatest,diagnosticModules,inbodyLatest,masuyamaLatest,priority,groups,trends,counts,ctc:ctcData,dateStart:dates[0]||"",dateEnd:dates.at(-1)||"",duplicateResultsSuppressed,importAudit,sourceAudit}
 }
