  let match=raw.match(/(-?\d+(?:\.\d+)?)\s*(?:-|–|—|to)\s*(-?\d+(?:\.\d+)?)/i);
  if(match){
   const low=Number(match[1]),high=Number(match[2]);
   if(Number.isFinite(low)&&Number.isFinite(high))return{low:Math.min(low,high),high:Math.max(low,high),type:"range"}
  }
