  if(match&&Number.isFinite(Number(match[1])))return{high:Number(match[1]),type:"upper"};
  match=raw.match(/(?:>=|≥|>)\s*(-?\d+(?:\.\d+)?)/);
  if(match&&Number.isFinite(Number(match[1])))return{low:Number(match[1]),type:"lower"};
  return null
