  let min=Math.min(...domain),max=Math.max(...domain),span=max-min;
  if(!Number.isFinite(span)||span===0){span=Math.max(Math.abs(max),1);min-=span*.25;max+=span*.25}
  else{const pad=span*.16;min-=pad;max+=pad}
