 function oncotrailTotalCtcRow(row){
  const code=text(row?.testCode||row?.test_code).toLowerCase(),role=text(row?.ctcMeasurementRole||row?.ctc_measurement_role).toUpperCase();
  if(role==="TOTAL_CTC")return true;
  if(code==="oncotrail_lung_ctc_count"||code==="oncotrail_ctc_count")return true;
  if(code)return false;
  const name=text(row?.name||row?.display_name);
  return /(?:^|—|\b)(?:Lung\s+)?CTC\s+count(?:\b|$)/i.test(name)&&!/EpCAM|subset|CD45/i.test(name)
 }
 function oncotrailEpCamSubsetRow(row){
  const code=text(row?.testCode||row?.test_code).toLowerCase(),role=text(row?.ctcMeasurementRole||row?.ctc_measurement_role).toUpperCase();
  return role==="EPCAM_POSITIVE_SUBSET"||code==="oncotrail_epcam_positive_ctc_count"
 }
 function metastatOrganKey(row){
  const code=text(row?.testCode||row?.test_code).toLowerCase();
  const location=text(row?.metastasisLocation||row?.metastasis_location||row?.section||row?.subGroupName||row?.sub_group_name||row?.name).toLowerCase();
  if(code.includes("pleura_")||/\bpleura\b/.test(location))return"pleura";
  if(code.includes("skin_")||/\bskin\b/.test(location))return"skin";
  if(code.includes("lung_")||/\blung\b/.test(location))return"lung";
  if(code.includes("bone_")||/\bbone\b/.test(location))return"bone";
  if(code.includes("liver_")||/\bliver\b/.test(location))return"liver";
  if(code.includes("brain_")||/\bbrain\b/.test(location))return"brain";
  return"general"
 }
 function metastatOrganLabel(key,options){
  const labels={pleura:bilingual("เยื่อหุ้มปอด","Pleura",options),skin:bilingual("ผิวหนัง","Skin",options),lung:bilingual("ปอด","Lung",options),bone:bilingual("กระดูก","Bone",options),liver:bilingual("ตับ","Liver",options),brain:bilingual("สมอง","Brain",options),general:bilingual("ภาพรวม / ไม่ระบุอวัยวะ","General / uncategorised",options)};
  return labels[key]||key
 }
 function metastatRowSignal(row){
  const reported=text(row?.reportedResult||row?.reported_result||row?.value).toUpperCase();
  if(/UP\s*REGULATED|POSITIVE|INCREASED|HIGH/.test(reported))return 2;
  if(/DIM|BORDERLINE/.test(reported))return 1;
  return 0
 }
 function metastatPrimaryDestinations(rows){
  const row=(rows||[]).find(item=>text(item?.testCode||item?.test_code).toLowerCase()==="metastat_primary_destination_trend");
  const raw=text(row?.value??row?.reportedResult??row?.reported_result??row?.name).toLowerCase();
  const found=[];
  [["pleura",/pleura/g],["skin",/skin/g],["lung",/lung/g],["bone",/bone/g],["liver",/liver/g],["brain",/brain/g]].forEach(([key,pattern])=>{const match=pattern.exec(raw);if(match)found.push({key,index:match.index})});
  return found.sort((a,b)=>a.index-b.index).map(item=>item.key)
 }
 function metastatPrimaryDestination(rows){return metastatPrimaryDestinations(rows)[0]||""}
 function metastatUpregulatedOrganFindings(rows){
  const groups=new Map(),primary=new Set(metastatPrimaryDestinations(rows));
  (rows||[]).forEach(row=>{
   const code=text(row?.testCode||row?.test_code).toLowerCase();
   if(code==="metastat_primary_destination_trend")return;
   if(metastatRowSignal(row)<2)return;
   const key=metastatOrganKey(row);if(key==="general")return;
   if(!groups.has(key))groups.set(key,{key,primary:primary.has(key),markers:[]});
   const name=text(row?.name);if(name&&!groups.get(key).markers.includes(name))groups.get(key).markers.push(name)
  });
  return [...groups.values()].sort((a,b)=>Number(b.primary)-Number(a.primary)||a.key.localeCompare(b.key))
 }
 function metastatOrganRanking(rows){
  // Compatibility helper retained for callers/tests. v10.313 deliberately does
  // NOT create a probability-like rank from comparator levels. Only explicit
  // source-report primary destinations and UP REGULATED markers are surfaced.
  const primaryList=metastatPrimaryDestinations(rows),up=metastatUpregulatedOrganFindings(rows),keys=new Set([...primaryList,...up.map(item=>item.key)]);
  return [...keys].map(key=>{
   const primaryIndex=primaryList.indexOf(key),finding=up.find(item=>item.key===key);
   return{key,primary:primaryIndex>=0,primaryOrder:primaryIndex>=0?primaryIndex+1:null,strong:finding?.markers?.length||0,supportive:0,markers:finding?.markers||[],score:primaryIndex>=0?1000-primaryIndex:0}
  }).sort((a,b)=>Number(b.primary)-Number(a.primary)||(a.primaryOrder||99)-(b.primaryOrder||99)||b.strong-a.strong||a.key.localeCompare(b.key))
 }
 function metastatRankingText(rows,options){
  const primary=metastatPrimaryDestinations(rows),up=metastatUpregulatedOrganFindings(rows);
  const primaryText=primary.length?primary.map(key=>metastatOrganLabel(key,options)).join(", "):bilingual("ไม่พบ Primary destination ที่ห้องปฏิบัติการสรุปไว้","No source-reported primary destination",options);
  const other=up.filter(item=>!primary.includes(item.key));
  const otherText=other.length?other.map(item=>`${metastatOrganLabel(item.key,options)} (${item.markers.join(", ")})`).join(" · "):"";
  return otherText?`${bilingual("Primary destination ตาม RGCC","RGCC primary destination",options)}: ${primaryText} · ${bilingual("UP REGULATED อื่น","Other UP REGULATED organ markers",options)}: ${otherText}`:`${bilingual("Primary destination ตาม RGCC","RGCC primary destination",options)}: ${primaryText}`
 }
