  const {level,previous,dates,reportDate}=context,configs=masuyamaConfigs(),targetRows=configs.map(([code,label,target])=>[masuyamaRowByCode(rows,code),label,target]).filter(([row])=>row),reached=targetRows.filter(([row])=>masuyamaTargetLabel(row).state==="normal").map(([,label])=>label),attention=targetRows.filter(([row])=>masuyamaTargetLabel(row).state!=="normal").map(([,label])=>label);
