  const note=options.note?`<section class="booklet-clinical-note ${options.reviewed?"reviewed":"draft"}"><b>${bilingual("หมายเหตุจากทีมรักษา","Care team note",options)}</b><p>${esc(options.note).replace(/\n/g,"<br>")}</p><span>${options.reviewed?bilingual("ตรวจทานแล้ว","Reviewed",options):bilingual("ฉบับรอตรวจทาน — ยังไม่ควรส่งผู้ป่วย","Draft — not ready for patient release",options)}</span></section>`:"";
