  const specialisedEn=`High/Low counts on this page apply to General Laboratory only. ${specialisedList} use separate diagnostic modules so method-specific classes, titers, cutoffs and assay outputs are not treated like routine chemistry.`;
  const specializedReadNote=!specialisedNames.length?"":`<div class="booklet-safety-box"><b>${bilingual("วิธีอ่านรายงานนี้","How to read this report",options)}</b><p>${bilingual(specialisedThai,specialisedEn,options)}</p></div>`;
  const moduleGrid=diagnosticModuleSummaryGrid(model);
