  return`<section class="booklet-inbody-executive"><div class="booklet-inbody-executive-head"><div><span>INBODY 720 · BODY COMPOSITION</span><h2>${bilingual("ภาพรวมองค์ประกอบร่างกาย","Body-composition overview",options)}</h2><p>${bilingual("วิเคราะห์องค์ประกอบร่างกายด้วยความต้านทานไฟฟ้า (BIA) และแสดงกล้ามเนื้อ ไขมัน สมดุลน้ำ และข้อมูลรายส่วน","Bioelectrical impedance analysis (BIA) showing muscle, fat, fluid balance and segmental measures",options)}</p></div><b>${bilingual("หมวดเฉพาะทาง","Specialized module",options)}</b></div><div class="booklet-inbody-metric-grid">${metric("inbody_weight",bilingual("น้ำหนัก","Weight",options))}${metric("inbody_skeletal_muscle_mass",bilingual("มวลกล้ามเนื้อลาย","Skeletal muscle mass",options))}${metric("inbody_body_fat_mass",bilingual("มวลไขมัน","Body fat mass",options))}${metric("inbody_bmi",bilingual("ดัชนีมวลกาย (BMI)","Body mass index (BMI)",options))}${metric("inbody_percent_body_fat",bilingual("ร้อยละไขมันในร่างกาย (PBF)","Percent body fat (PBF)",options))}${metric("inbody_visceral_fat_area",bilingual("พื้นที่ไขมันช่องท้อง (VFA)","Visceral fat area (VFA)",options))}</div><div class="booklet-inbody-dashboard-row"><article><h3>${bilingual("เป้าหมายการปรับองค์ประกอบร่างกายจากเครื่อง","Device body-composition targets",options)}</h3><div class="booklet-inbody-control-grid">${control("inbody_target_weight",bilingual("น้ำหนักเป้าหมาย","Target weight",options))}${control("inbody_weight_control",bilingual("การปรับน้ำหนัก","Weight control",options))}${control("inbody_fat_control",bilingual("การปรับไขมัน","Fat control",options))}${control("inbody_muscle_control",bilingual("การปรับกล้ามเนื้อ","Muscle control",options))}</div></article><article><h3>${bilingual("สมดุลน้ำและข้อมูลเพิ่มเติม","Fluid balance and additional measures",options)}</h3><div class="booklet-inbody-sidefacts"><div><span>${bilingual("สัดส่วนน้ำนอกเซลล์ต่อน้ำทั้งหมด (ECW/TBW)","Extracellular/total body water (ECW/TBW)",options)}</span><b>${currentWater?esc(valueText(currentWater)):"—"}</b></div><div><span>${bilingual("ค่า ECW/TBW จากประวัติในเครื่อง","History ECW/TBW",options)}</span><b>${history?esc(valueText(history)):"—"}</b></div><div><span>${bilingual("ระดับน้ำหนักเทียบมาตรฐาน","Obesity degree",options)}</span><b>${obesity?`${esc(valueText(obesity))} ${esc(obesity.unit||"%")}`:"—"}</b></div><div><span>${bilingual("คะแนนสมรรถภาพจากเครื่อง","Fitness score",options)}</span><b>${fitness?esc(valueText(fitness)):"—"}</b></div></div></article></div><div class="booklet-safety-box"><b>${bilingual("ที่มาของข้อมูล","Data source",options)}</b><p>${bilingual("ตัวเลขในหน้านี้มาจากรายงาน InBody ต้นฉบับและการตรวจความสอดคล้องของข้อมูลในแผ่นเดียวกัน หากต้นฉบับไม่ได้ระบุช่วงอ้างอิง ระบบจะไม่สร้างเกณฑ์ขึ้นเอง","Values on this page come from the source InBody report and same-sheet consistency checks. MIW does not invent a reference interval when the source does not provide one.",options)}</p></div><a class="booklet-inbody-interpret-link booklet-click-card" href="#inbody-clinical-interpretation">${bilingual("เปิดคำอธิบายผล InBody →","Open InBody interpretation →",options)}</a></section>`
