 function inbodyExecutivePage(model){return{section:"InBody 720",title:"ภาพรวม InBody 720",kind:"inbody-specialized-summary",tocPath:["InBody 720 / Body Composition","ภาพรวม"],content:`${pageHeader(model,"InBody 720 · Body Composition")}<div class="booklet-section-title compact" id="${bookletGroupAnchor("Body Composition")}"><span>IB</span><div><h1>InBody 720 — Body Composition</h1><p>ภาพรวมเฉพาะทางก่อนอ่านรายละเอียดองค์ประกอบร่างกายและ Segmental Analysis</p></div></div>${inbodyExecutiveSummary(model)}`}}
 function inbodyFriendlyText(value,options){
  let s=text(value);if(!s)return s;
  const en=bookletEnglishMode(options);
  if(en)return s.replace(/\bSMM\b(?!\))/g,"skeletal muscle mass (SMM)").replace(/\bPBF\b(?!\))/g,"percent body fat (PBF)").replace(/\bVFA\b(?!\))/g,"visceral fat area (VFA)").replace(/\bBMR\b(?!\))/g,"basal metabolic rate (BMR)").replace(/\bWHR\b(?!\))/g,"waist-to-hip ratio (WHR)").replace(/\bECW\/TBW\b(?!\))/g,"extracellular/total body water (ECW/TBW)").replace(/Segmental Lean/gi,"segmental lean mass").replace(/Lean \/ Ideal Lean/gi,"segmental lean relative to device ideal");
  return s.replace(/\bSMM\b(?!\))/g,"มวลกล้ามเนื้อลาย (SMM)").replace(/\bPBF\b(?!\))/g,"ร้อยละไขมันในร่างกาย (PBF)").replace(/\bVFA\b(?!\))/g,"พื้นที่ไขมันช่องท้อง (VFA)").replace(/\bBMR\b(?!\))/g,"อัตราการเผาผลาญพื้นฐาน (BMR)").replace(/\bWHR\b(?!\))/g,"อัตราส่วนเอวต่อสะโพก (WHR)").replace(/\bECW\/TBW\b(?!\))/g,"สัดส่วนน้ำนอกเซลล์ต่อน้ำทั้งหมด (ECW/TBW)").replace(/Segmental Lean/gi,"มวลกล้ามเนื้อรายส่วน").replace(/Lean \/ Ideal Lean/gi,"มวลกล้ามเนื้อรายส่วนเทียบเป้าหมายของเครื่อง").replace(/body-recomposition pattern/gi,"รูปแบบลดไขมันพร้อมรักษาหรือเพิ่มกล้ามเนื้อ").replace(/body recomposition/gi,"การลดไขมันพร้อมรักษาหรือเพิ่มกล้ามเนื้อ");
 }
 function inbodyPatientDomainCopy(id,options){
  const th={fat:["ไขมันในร่างกาย","ดูร้อยละไขมันและมวลไขมันร่วมกับแนวโน้ม ไม่ควรดูน้ำหนักอย่างเดียว"],muscle:["มวลกล้ามเนื้อ","ดูทั้งมวลกล้ามเนื้อรวมและกล้ามเนื้อรายส่วน เพื่อไม่ให้ค่ารวมบดบังส่วนที่ต่ำกว่าเป้าหมาย"],visceral:["ไขมันช่องท้อง","ติดตามร่วมกับรอบเอว น้ำตาล ไขมันในเลือด และภาวะไขมันพอกตับเมื่อมีข้อมูล"],metabolic:["อัตราการเผาผลาญพื้นฐาน","เป็นค่าประมาณพลังงานพื้นฐานจากเครื่อง ไม่ใช่จำนวนแคลอรีที่ควรรับประทานต่อวันโดยอัตโนมัติ"],fluid:["สมดุลน้ำในร่างกาย","ใช้ติดตามแนวโน้มเมื่อวัดในสภาวะใกล้เคียงกัน ไม่ใช้ค่าเดียววินิจฉัยภาวะบวมหรือคั่งน้ำ"],segmental:["กล้ามเนื้อและไขมันรายส่วน","เปรียบเทียบแขน ขา และลำตัว เพื่อดูการกระจายและความสมดุลขององค์ประกอบร่างกาย"],weight:["เป้าหมายจากเครื่อง","เป็นค่าช่วยวางแผนการลดไขมันและรักษาหรือเพิ่มกล้ามเนื้อ ไม่ใช่คำสั่งรักษาอัตโนมัติ"]};
  const en={fat:["Body fat","Review percent body fat and fat mass together with serial trends rather than weight alone."],muscle:["Muscle mass","Review total skeletal muscle and segmental lean mass so a global value does not hide regional deficits."],visceral:["Visceral fat","Trend with waist measures, glucose, lipids and fatty-liver context when available."],metabolic:["Basal metabolic rate","A device estimate of resting energy use; it is not an automatic daily calorie prescription."],fluid:["Body fluid balance","Use serial measurements under comparable conditions; a single value does not diagnose edema or fluid overload."],segmental:["Segmental muscle and fat","Compare arms, legs and trunk to understand distribution and left-right balance."],weight:["Device target","A planning aid for fat reduction and muscle preservation/gain, not an automatic treatment order."]};
  return (bookletEnglishMode(options)?en:th)[id]||[id,""]
 }
 function inbodyGlossary(options){
  const rows=bookletEnglishMode(options)?[["BMI","Body mass index"],["SMM","Skeletal muscle mass"],["PBF","Percent body fat"],["VFA","Visceral fat area"],["WHR","Waist-to-hip ratio"],["BMR","Basal metabolic rate"],["ECW/TBW","Extracellular water / total body water"],["BIA","Bioelectrical impedance analysis"]]:[["BMI","ดัชนีมวลกาย"],["SMM","มวลกล้ามเนื้อลาย"],["PBF","ร้อยละไขมันในร่างกาย"],["VFA","พื้นที่ไขมันช่องท้อง"],["WHR","อัตราส่วนเอวต่อสะโพก"],["BMR","อัตราการเผาผลาญพื้นฐาน"],["ECW/TBW","สัดส่วนน้ำนอกเซลล์ต่อน้ำทั้งหมด"],["BIA","การวิเคราะห์องค์ประกอบร่างกายด้วยความต้านทานไฟฟ้า"]];
  return`<section class="booklet-inbody-glossary"><h3>${bilingual("คำย่อที่ใช้ในรายงาน","Abbreviations used in this report",options)}</h3><div class="booklet-inbody-glossary-grid">${rows.map(([a,b])=>`<div><b>${esc(a)}</b><span>${esc(b)}</span></div>`).join("")}</div></section>`
 }
 function inbodyClinicalInterpretationHtml(model){
  const items=(model.rows||[]).filter(row=>bookletGroupKey(row)==="Body Composition"),map=inbodyCodeMap(items),options=model.options;
  const lang=options?.language==="en"?"en":"th",interpretation=MIW.InBodyInterpretation?.build?.(items,{latestRows:[...map.values()],lang});
  if(!interpretation?.available)return`<div class="booklet-safety-box"><b>${bilingual("ยังสร้างคำอธิบายผล InBody ไม่ได้","InBody interpretation unavailable",options)}</b><p>${bilingual("ยังไม่มีข้อมูล InBody ที่ยืนยันเพียงพอสำหรับการแปลผล","There are not enough verified InBody data for interpretation.",options)}</p></div>`;
  const domainIcon={fat:"F",muscle:"M",visceral:"V",metabolic:"E",fluid:"W",segmental:"S",weight:"↔"};
  const domains=interpretation.domains.map(d=>{const copy=inbodyPatientDomainCopy(d.id,options);return`<article class="booklet-inbody-domain tone-${esc(d.tone)}"><span>${esc(domainIcon[d.id]||"IB")}</span><div><h3>${esc(copy[0])}</h3><b>${esc(inbodyFriendlyText(d.headline,options))}</b><p>${esc(copy[1])}</p></div></article>`}).join("");
  const priorities=interpretation.priorities.slice(0,4).map((p,index)=>`<li class="tone-${esc(p.tone)}"><span>${index+1}</span><div><b>${esc(inbodyFriendlyText(p.title,options))}</b><p>${esc(inbodyFriendlyText(p.detail,options))}</p></div></li>`).join("");
  const trend=interpretation.trend?.available?`<section class="booklet-inbody-trend"><h3>${bilingual("แนวโน้มองค์ประกอบร่างกาย","Body-composition trend",options)}</h3><div>${interpretation.trend.cards.map(c=>`<article><b>${esc(c.name)}</b><strong class="trend-${esc(c.direction)}">${c.direction==="up"?"↑":c.direction==="down"?"↓":"—"}</strong><span>${esc(c.previous)} → ${esc(c.latest)}</span><small>${esc(c.previousDate||"")} → ${esc(c.latestDate||"")}</small></article>`).join("")}</div><p>${bilingual("ลูกศรบอกทิศทางของตัวเลขเท่านั้น ไม่ได้หมายความว่าดีขึ้นหรือแย่ลงเสมอ","Arrows show numeric direction only and do not automatically mean improvement or deterioration.",options)}</p></section>`:"";
  const sourceNotes=interpretation.sourceNotes?.length?`<section class="booklet-inbody-source-notes"><h3>${bilingual("ข้อควรรู้เกี่ยวกับค่าจากเครื่อง","Important notes about device-derived values",options)}</h3><ul>${interpretation.sourceNotes.slice(0,3).map(n=>`<li>${esc(inbodyFriendlyText(n,options))}</li>`).join("")}</ul></section>`:"";
  return`<section class="booklet-inbody-clinical"><div class="booklet-inbody-pattern tone-${esc(interpretation.pattern.tone)}"><span>${bilingual("ภาพรวมการแปลผล","INTERPRETATION OVERVIEW",options)}</span><h2>${esc(inbodyFriendlyText(interpretation.pattern.title,options))}</h2><p>${esc(inbodyFriendlyText(interpretation.pattern.summary,options))}</p></div><div class="booklet-inbody-domain-grid">${domains}</div><section class="booklet-inbody-priorities"><h3>${bilingual("สิ่งที่ควรติดตาม","Follow-up priorities",options)}</h3><ol>${priorities}</ol></section>${trend}${sourceNotes}${inbodyGlossary(options)}<div class="booklet-safety-box source"><b>${bilingual("ตัวเลขจากต้นฉบับและคำอธิบายของ MIW","Source values and MIW interpretation",options)}</b><p>${bilingual("ตัวเลขและช่วงอ้างอิงมาจากรายงาน InBody ที่ระบบยืนยันแล้ว ส่วนคำอธิบายเป็นการช่วยอ่านผลและไม่เขียนทับค่าต้นฉบับ","Values and reference intervals come from verified InBody source data. MIW adds explanatory text without overwriting source values.",options)}</p><p>${bilingual("การแปลผลนี้ไม่ใช่การวินิจฉัยโรคหรือคำสั่งรักษาอัตโนมัติ ต้องพิจารณาร่วมกับอาการ การตรวจร่างกาย สมรรถภาพ และข้อมูลทางคลินิก","This interpretation is not an automatic diagnosis or treatment order; correlate with symptoms, examination, function and clinical data.",options)}</p></div></section>`
 }
