  ctc.specialized.forEach(item=>{const date=rowDate(item.rows[0]);cards.push(`<a class="booklet-ctc-report-card booklet-click-card" href="#${ctcReportAnchor(item,item.type)}"><span>${esc(ctcReportLabel(item.type).toUpperCase())}</span><h2>${esc(dateThai(date))}</h2><div><b>${item.rows.length}</b><small>${bilingual("รายการในรายงาน","report items",options)}</small><b>✓</b><small>VERIFIED</small></div><p>${esc(sourceDocument(item.rows[0]))}</p></a>`)});
  return{section:plainBilingual("CTC","CTC",options),title:plainBilingual("ภาพรวมรายงาน CTC","CTC report overview",options),kind:"ctc-overview",tocPath:[plainBilingual("CTC และการตรวจจากเซลล์มะเร็ง","CTC and tumor-cell based tests",options),plainBilingual("ภาพรวมรายงาน CTC","CTC report overview",options)],content:`${pageHeader(model,plainBilingual("รายงาน CTC เฉพาะทาง","Specialised CTC reports",options))}<div class="booklet-section-title" id="ctc-overview"><span>CTC</span><div><h1>${bilingual("ภาพรวมรายงานที่พบ","Available CTC reports",options)}</h1><p>${bilingual(`${ctc.reportCount} รายงาน · ${ctc.rowCount} รายการ · คลิกการ์ดเพื่อไปยังรายงานนั้น`,`${ctc.reportCount} ${countNoun(ctc.reportCount,"report","reports")} · ${ctc.rowCount} ${countNoun(ctc.rowCount,"item","items")} · click a card to open that report`,options)}</p></div></div><div class="booklet-ctc-report-grid">${cards.join("\n")}</div>${ctc.reviewCount?`<div class="booklet-ctc-excluded review"><b>${bilingual(`มี ${ctc.reviewCount} รายการที่ควรทวนซ้ำกับต้นฉบับ`,`${ctc.reviewCount} items should be rechecked against the source report`,options)}</b></div>`:""}${ctc.excludedCount?`<div class="booklet-ctc-excluded"><b>${bilingual(`${ctc.excludedCount} รายการยังอ่านค่าไม่สมบูรณ์`,`${ctc.excludedCount} items remain incompletely resolved`,options)}</b></div>`:""}<div class="booklet-safety-box"><b>${bilingual("ข้อจำกัดสำคัญ","Important limitations",options)}</b><p>${bilingual("ผล CTC และการทดสอบเฉพาะทางเป็นข้อมูลประกอบ ไม่ยืนยันการตอบสนองต่อยา การกลายพันธุ์ หรือตำแหน่งแพร่กระจายโดยลำพัง","CTC and specialised assay findings are supplementary and do not independently establish drug response, genomic alteration or metastatic location.",options)}</p></div>`}
