  match=raw.match(/Also can be used\s+(.+?)(?=\s+The\s+(?:specific\s+)?tumou?r\s+appears\b|\s+(?:specific\s+)?tumou?r\s+appears\s+to\s+have\s+resisting\s+populations\b|\s+resisting\s+populations\s+because\s+of\b|\s+MDR1\s+overexpression\b|$)/i);
