  const topNatural=oncoTopRows(item,"NATURAL",10).map(row=>`${text(row.name)} (${oncoResultValue(row)})`);
  const resistance=item.rows.filter(row=>text(row.group).toUpperCase()==="GENE"&&/MDR1|MRP1|GST|LRP/i.test(text(row.name)))
   .sort((a,b)=>Math.abs(finite(b.value)||0)-Math.abs(finite(a.value)||0)).map(row=>`${text(row.name)} ${oncoResultValue(row)}`);
