 function oncoSourceSections(item,options){
  const map=new Map();
  item.rows.forEach(row=>{
   const group=text(row.group).toUpperCase()||"OTHER";
   const section=text(row.section||row.subGroupName)||oncoGroupLabel(group,options);
   const key=`${group}|${section}`;
   if(!map.has(key))map.set(key,{group,section,rows:[],page:finite(row.page||row.source_page_number)});
   map.get(key).rows.push(row)
  });
  return[...map.values()].sort((a,b)=>(a.page??999)-(b.page??999)||a.group.localeCompare(b.group)||a.section.localeCompare(b.section))
 }
