  const high=threeLevel.filter(row=>(finite(row.value)||0)>=80).sort((a,b)=>(finite(b.value)||0)-(finite(a.value)||0)).slice(0,8).map(row=>`${text(row.name)} ${oncoResultValue(row)}`);
  const partial=threeLevel.filter(row=>(finite(row.value)||0)>=30&&(finite(row.value)||0)<80).sort((a,b)=>(finite(b.value)||0)-(finite(a.value)||0)).slice(0,8).map(row=>`${text(row.name)} ${oncoResultValue(row)}`);
