 function compactOncoResultValue(row){
  const group=text(row?.group).toUpperCase();
  if(group==="ADDITIONAL"){
   const before=text(row?.valueWithout??row?.reportLayer?.valueWithoutSubstance),after=text(row?.valueWith??row?.reportLayer?.valueWithSubstance),effect=text(row?.effectiveness||row?.status),reportedClass=text(row?.reportedClass||row?.reportLayer?.reportedClass);
   return[reportedClass,before||after?`${before||"—"} → ${after||"—"}`:"",effect].filter(Boolean).join(" · ")||oncoResultValue(row)
  }
  return oncoResultValue(row)
 }
