  const axes=angles.map((_,index)=>`<line x1="${cx}" y1="${cy}" x2="${(cx+Math.cos(angles[index])*maxR).toFixed(1)}" y2="${(cy+Math.sin(angles[index])*maxR).toFixed(1)}"/>`).join("");
  const levelText=`<text x="${cx}" y="${cy-maxR+12}" text-anchor="middle" class="ring-label">3</text><text x="${cx}" y="${cy-(maxR*2/3)+12}" text-anchor="middle" class="ring-label">2</text><text x="${cx}" y="${cy-(maxR/3)+12}" text-anchor="middle" class="ring-label">1</text>`;
  const prevPoly=previous?`<polygon points="${poly(previous)}" class="prev"/>`:"";
