  const slots=Array.from({length:10},(_,index)=>series[index]||null),width=520,height=190,left=60,top=12,plotW=360,plotH=122,colW=plotW/10,rowH=plotH/6;
  const rankToY=rank=>(top+((6-rank)+0.5)*rowH).toFixed(1),colToX=index=>(left+(index+0.5)*colW).toFixed(1);
  const bg=`<rect x="${left}" y="${top}" width="${plotW}" height="${(rowH*2).toFixed(1)}" class="band-upper semantic-green"/><rect x="${left}" y="${(top+rowH*2).toFixed(1)}" width="${plotW}" height="${(rowH*2).toFixed(1)}" class="band-mid semantic-amber"/><rect x="${left}" y="${(top+rowH*4).toFixed(1)}" width="${plotW}" height="${(rowH*2).toFixed(1)}" class="band-low semantic-red"/>`;
  const hLines=Array.from({length:7},(_,i)=>`<line x1="${left}" y1="${(top+i*rowH).toFixed(1)}" x2="${left+plotW}" y2="${(top+i*rowH).toFixed(1)}" class="grid"/>`).join("");
  const vLines=Array.from({length:11},(_,i)=>`<line x1="${(left+i*colW).toFixed(1)}" y1="${top}" x2="${(left+i*colW).toFixed(1)}" y2="${top+plotH}" class="grid"/>`).join("");
  const yLabels=["5","4","3H","3L","2","1"].map((label,index)=>`<text x="${left-10}" y="${(top+(index+0.5)*rowH).toFixed(1)}" text-anchor="end" dominant-baseline="middle" class="y-label">${label}</text>`).join("");
  const pts=slots.map((item,index)=>item?`${colToX(index)},${rankToY(masuyamaLevelRank(valueText(item)))}`:"").filter(Boolean);
