 function inbodyBookletNumber(value){
  if(value===null||value===undefined||value==="")return null;
  const normalized=String(value).normalize("NFKC").replace(/[−–—]/g,"-").replace(/,/g,".").replace(/\s+/g,"").replace(/^([+-]?)\.(\d+)/,"$10.$2");
  const match=normalized.match(/[+-]?\d+(?:\.\d+)?/);if(!match)return null;const n=Number(match[0]);return Number.isFinite(n)?n:null
 }
 function inbodyBookletNumberFromRow(row){
  for(const value of [row?.value,row?.value_raw,row?.reported_value_raw,row?.valueNumeric,row?.value_numeric]){const n=inbodyBookletNumber(value);if(n!==null)return n}return null
 }
 function inbodyBookletEvidenceText(row){
  const evidence=[...(Array.isArray(row?.sourceEvidence)?row.sourceEvidence:[]),...(Array.isArray(row?.source_evidence)?row.source_evidence:[])].map(item=>text(item?.type||item?.kind||item?.mode));
  return`${evidence.join(" ")} ${text(row?.sourceLine||row?.source_line)} ${text(row?.profile||row?.specializedProfile||row?.specialized_profile)}`.toLowerCase()
 }
 function inbodyBookletAuthority(row){
  const e=inbodyBookletEvidenceText(row);let score=0;
  if(/inbody-v10\.306-fixed-history-source-matrix|inbody-v10\.306-fixed-weight-control-source-matrix/.test(e))score+=22000;
  if(/inbody-v10\.306-defined-from-fixed-source-matrix|inbody-v10\.306-defined-weight-control-identities/.test(e))score+=18000;
  if(/inbody-weight-control-bundle/.test(e))score+=15000;
  if(/inbody-history-bundle-reconciliation|history ecw\/tbw trailing-column/.test(e))score+=14500;
  if(/inbody-bottom-water-bundle/.test(e))score+=14000;
  if(/inbody-segment-row/.test(e))score+=12500;
  if(/inbody-micro-roi/.test(e))score+=9500;
  if(/inbody-current-sheet-reconciliation|source reconciliation/.test(e))score+=9000;
  if(/inbody-vfa-marker-reconciliation/.test(e))score+=9000;
  if(/inbody-same-sheet-definition-rescue|definition rescue/.test(e))score+=7000;
  if(/inbody-deterministic-roi/.test(e))score+=6500;
  if(/inbody-roi/.test(e))score+=3500;
  if(row?.inbodyRoiLocked===true||row?.inbody_roi_locked===true)score+=700;
  if(row?.inbodyValidationPassed===true||row?.inbody_validation_passed===true)score+=500;
  if(row?.manuallyVerified===true)score+=250;
  score+=Math.min(99,Math.max(0,Number(row?.confidence||0)));
  return score
 }
 function inbodyBookletDecimals(value){
  const raw=text(value).replace(/,/g,".").replace(/\s+/g,"");const m=raw.match(/\.([0-9]+)/);return m?m[1].length:0
 }
 function inbodyBookletValuePlausible(code,row){
  const v=inbodyBookletNumberFromRow(row);if(v===null)return false;const raw=row?.value??row?.value_raw??row?.reported_value_raw??v,dec=inbodyBookletDecimals(raw);
  if(code==="inbody_obesity_degree")return v>=40&&v<=250;
  if(code==="inbody_history_ecw_tbw"||code==="inbody_ecw_tbw"||/_ecw_tbw$/.test(code))return v>=.20&&v<=.60&&(dec===0||dec>=3);
  if(code==="inbody_ecf_tbf"||/_ecf_tbf$/.test(code))return v>=.20&&v<=.50&&(dec===0||dec>=3);
  if(code==="inbody_target_weight")return v>=20&&v<=300;
  if(["inbody_weight_control","inbody_fat_control","inbody_muscle_control"].includes(code))return v>=-150&&v<=150;
  if(/_lean_pct$/.test(code))return v>=40&&v<=220&&(dec===0||dec===1);
  if(/_fat_pct$/.test(code))return v>=50&&v<=500&&dec===0;
  if(/_fat_mass$/.test(code))return v>=.1&&v<=80&&(dec===0||dec===1);
  if(/_lean_mass$/.test(code)){const limb=!/_trunk_/.test(code);return v>=.2&&v<=80&&(dec===0||dec===(limb?2:1))}
  if(code==="inbody_visceral_fat_area")return v>=1&&v<=300;
  return true
 }
 function inbodyBookletReferenceRaw(row){return text(row?.reference||row?.referenceRaw||row?.reference_raw||row?.reported_reference_raw)}
 function inbodyBookletReferencePlausible(code,raw){
  const normalized=text(raw).replace(/[−–—~～]/g,"-").replace(/,/g,".").replace(/(\d+)\.\s+(\d+)/g,"$1.$2");
  const values=(normalized.match(/\d+(?:\.\d+)?/g)||[]).map(Number).filter(Number.isFinite);if(values.length<2)return false;
  const lo=Math.min(values[0],values[1]),hi=Math.max(values[0],values[1]);if(!(hi>lo))return false;
  if(code==="inbody_bmi")return lo>=10&&lo<=35&&hi>=15&&hi<=45;
  if(code==="inbody_percent_body_fat")return lo>=5&&lo<=45&&hi>=10&&hi<=60;
  if(code==="inbody_waist_hip_ratio")return lo>=.5&&lo<=1.1&&hi>=.6&&hi<=1.2;
  if(code==="inbody_obesity_degree")return lo>=40&&lo<=160&&hi>=60&&hi<=220;
  if(code==="inbody_bmr")return lo>=500&&lo<=3500&&hi>=700&&hi<=5000;
  if(code==="inbody_minerals")return lo>=1&&lo<=6&&hi>=2&&hi<=6&&hi-lo>=.25&&hi-lo<=2.5;
  const mid=(lo+hi)/2,width=hi-lo;return width/Math.max(mid,1e-6)>=(code==="inbody_waist_hip_ratio"?.07:.08)
 }
 function inbodyBookletVirtualRow(template,code,value,unit=""){
  const base=template?{...template}:{testCode:code,test_code:code,name:code};const numeric=Number(value),signed=["inbody_weight_control","inbody_fat_control","inbody_muscle_control"].includes(code);
  let raw=Number.isFinite(numeric)?String(numeric):text(value);if(signed&&numeric>0&&!raw.startsWith("+"))raw=`+${raw}`;
  base.testCode=base.testCode||code;base.test_code=base.test_code||code;base.value=raw;base.value_raw=raw;base.reported_value_raw=raw;base.valueNumeric=numeric;base.value_numeric=numeric;if(unit)base.unit=unit;base._bookletInBodyCanonical=true;return base
 }
 function inbodyBookletCandidateRows(items,code){
  return(items||[]).filter(row=>text(row?.testCode||row?.test_code).toLowerCase()===code&&inbodyBookletValuePlausible(code,row)).map(row=>({row,value:inbodyBookletNumberFromRow(row),score:inbodyBookletAuthority(row)})).sort((a,b)=>b.score-a.score)
 }
 function inbodyCodeMap(items){
  const grouped=new Map();
  (items||[]).forEach(row=>{if(row?.selected===false||row?.inbody_source_quarantined||row?.inbody_clinical_excluded)return;const code=text(row?.testCode||row?.test_code).toLowerCase();if(!code)return;if(!grouped.has(code))grouped.set(code,[]);grouped.get(code).push(row)});
  const map=new Map();
  for(const [code,candidates] of grouped){
   const valid=candidates.filter(row=>inbodyBookletValuePlausible(code,row)).sort((a,b)=>inbodyBookletAuthority(b)-inbodyBookletAuthority(a));
   const winner={...(valid[0]||candidates.sort((a,b)=>inbodyBookletAuthority(b)-inbodyBookletAuthority(a))[0])};if(!winner)continue;
   // Value and printed reference are independent source cells. Keep the strongest
   // source value, then recover the strongest structurally valid current-sheet
   // reference instead of inheriting a damaged legacy reference from that row.
   const refWinner=candidates.filter(row=>inbodyBookletReferencePlausible(code,inbodyBookletReferenceRaw(row))).sort((a,b)=>inbodyBookletAuthority(b)-inbodyBookletAuthority(a))[0];
   if(refWinner){const ref=inbodyBookletReferenceRaw(refWinner).replace(/[−–—~～]/g,"-").replace(/,/g,".").replace(/(\d+)\.\s+(\d+)/g,"$1.$2");winner.reference=ref;winner.referenceRaw=ref;winner.reference_raw=ref}
   map.set(code,winner)
  }
  // History ECW/TBW: reject legacy zero. A valid parser snapshot is acceptable
  // because v10.269+ stores this exact trailing History column before merge.
  if(!map.has("inbody_history_ecw_tbw")){
   const snapshot=(items||[]).map(row=>row?.inbody_source_truth_snapshot).find(x=>{const v=inbodyBookletNumber(x?.historyEcwTbw);return v!==null&&v>=.20&&v<=.60});
   if(snapshot){const template=map.get("inbody_ecw_tbw")||(items||[])[0];map.set("inbody_history_ecw_tbw",inbodyBookletVirtualRow(template,"inbody_history_ecw_tbw",snapshot.historyEcwTbw,"ratio"))}
  }
  // Resolve the four Weight Control values as ONE source bundle. A self-consistent
  // legacy bundle is not enough: current-sheet reconciliation / signed-row evidence
  // receives the decisive authority score.
  const weight=inbodyBookletNumberFromRow(map.get("inbody_weight"));
  const target=inbodyBookletCandidateRows(items,"inbody_target_weight").slice(0,10),wc=inbodyBookletCandidateRows(items,"inbody_weight_control").slice(0,10),fc=inbodyBookletCandidateRows(items,"inbody_fat_control").slice(0,10),mc=inbodyBookletCandidateRows(items,"inbody_muscle_control").slice(0,10);
  let bundle=null;
  if(weight!==null){
   for(const t of target)for(const w of wc)for(const f of fc)for(const m of mc){
    const e1=Math.abs((weight+w.value)-t.value),e2=Math.abs((f.value+m.value)-w.value);if(e1>.16||e2>.16)continue;
    const direct=[t,w,f,m].filter(x=>x.score>=7000).length,score=t.score+w.score+f.score+m.score+direct*12000-(e1+e2)*1000;if(!bundle||score>bundle.score)bundle={t,w,f,m,score}
   }
   if(!bundle){
    for(const w of wc)for(const f of fc)for(const m of mc){
     if(Math.abs((f.value+m.value)-w.value)>.16)continue;const direct=[w,f,m].filter(x=>x.score>=7000).length;if(direct<2)continue;
     const tv=Math.round((weight+w.value)*10)/10;if(tv<20||tv>300)continue;bundle={t:{row:target[0]?.row||map.get("inbody_target_weight"),value:tv,score:6500},w,f,m,score:w.score+f.score+m.score+direct*12000,derivedTarget:true}
    }
   }
  }
  if(bundle){
   map.set("inbody_target_weight",inbodyBookletVirtualRow(bundle.t.row,"inbody_target_weight",bundle.t.value,"kg"));
   map.set("inbody_weight_control",inbodyBookletVirtualRow(bundle.w.row,"inbody_weight_control",bundle.w.value,"kg"));
   map.set("inbody_fat_control",inbodyBookletVirtualRow(bundle.f.row,"inbody_fat_control",bundle.f.value,"kg"));
   map.set("inbody_muscle_control",inbodyBookletVirtualRow(bundle.m.row,"inbody_muscle_control",bundle.m.value,"kg"))
  }
  return map
 }
